'use client';

import { useId, type CSSProperties, type ReactNode } from 'react';
import './app-catalog.css';

export interface AppCatalogItem {
  id: string;
  title: string;
  description: string;
  icon: ReactNode;
  color: string;
  iconColor?: string;
  href?: string;
}
export interface AppCatalogProps {
  items: AppCatalogItem[];
  eyebrow?: string;
  title?: ReactNode;
  description?: ReactNode;
  onItemSelect?: (id: string) => void;
  className?: string;
}

/** A ruled app directory. Supply icons as ordinary SVG, images, or React nodes. */
export function AppCatalog({ items, eyebrow = 'App Store', title = 'Or start from one that’s already written.', description, onItemSelect, className = '' }: AppCatalogProps) {
  const uid = useId();
  return <section className={`ac-app-catalog ${className}`.trim()} aria-labelledby={`${uid}-title`}>
    <div className="ac-app-catalog__layout">
      <header className="ac-app-catalog__intro">
        {eyebrow && <p className="ac-app-catalog__eyebrow">{eyebrow}</p>}
        <h2 id={`${uid}-title`}>{title}</h2>
        {description && <p className="ac-app-catalog__description">{description}</p>}
      </header>
      <ul className="ac-app-catalog__grid">
        {items.map(item => {
          const content = <><span className="ac-app-catalog__icon" style={{ background: item.color, color: item.iconColor ?? '#24251f' } as CSSProperties} aria-hidden="true">{item.icon}</span><span className="ac-app-catalog__copy"><span className="ac-app-catalog__name">{item.title}</span><span className="ac-app-catalog__detail">{item.description}</span></span></>;
          return <li key={item.id}>{item.href ? <a className="ac-app-catalog__item" href={item.href} onClick={() => onItemSelect?.(item.id)}>{content}</a> : onItemSelect ? <button type="button" className="ac-app-catalog__item" onClick={() => onItemSelect(item.id)}>{content}</button> : <div className="ac-app-catalog__item">{content}</div>}</li>;
        })}
      </ul>
    </div>
  </section>;
}

.ac-app-catalog { --ac-app-theme-surface:#fcfbff; --ac-app-theme-ink:#181630; --ac-app-theme-muted:#68647f; --ac-app-theme-line:#e8e6ed; --ac-app-theme-hover:#f4f2f9; container-type:inline-size; padding:28px 0 84px; background:var(--ac-app-surface,var(--ac-app-theme-surface)); color:var(--ac-app-ink,var(--ac-app-theme-ink)); font-family:var(--ac-app-font,Geist,Arial,sans-serif); }
.ac-app-catalog *, .ac-app-catalog *::before, .ac-app-catalog *::after { box-sizing:border-box; }
.ac-app-catalog__layout { display:grid; grid-template-columns:minmax(0,4fr) minmax(0,8fr); gap:64px; width:100%; max-width:1200px; margin-inline:auto; padding-inline:32px; }
.ac-app-catalog__intro { min-width:0; }
.ac-app-catalog__eyebrow { margin:0; color:var(--ac-app-muted,var(--ac-app-theme-muted)); font-size:15px; line-height:1.5; font-weight:500; }
.ac-app-catalog__intro h2 { margin:16px 0 0; font-size:64px; line-height:1; font-weight:500; letter-spacing:-.02em; text-wrap:balance; }
.ac-app-catalog__description { margin:16px 0 0; max-width:380px; color:var(--ac-app-muted,var(--ac-app-theme-muted)); font-size:16px; line-height:1.55; text-wrap:pretty; }
.ac-app-catalog__grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); align-self:start; gap:1px; margin:0; padding:0; overflow:hidden; border:1px solid var(--ac-app-line,var(--ac-app-theme-line)); border-radius:24px; list-style:none; background:var(--ac-app-line,var(--ac-app-theme-line)); }
.ac-app-catalog__grid > li { display:flex; min-width:0; background:var(--ac-app-surface,var(--ac-app-theme-surface)); }
.ac-app-catalog__item { display:flex; flex-direction:column; align-items:flex-start; gap:16px; width:100%; min-width:0; padding:24px; border:0; background:transparent; color:inherit; font:inherit; text-align:left; text-decoration:none; transition:background-color 180ms ease; }
.ac-app-catalog__item:hover { background:var(--ac-app-hover,var(--ac-app-theme-hover)); }
.ac-app-catalog__item:is(a,button) { cursor:pointer; }
.ac-app-catalog__item:focus-visible { outline:2px solid currentColor; outline-offset:-5px; }
.ac-app-catalog__icon { display:grid; place-items:center; flex-shrink:0; width:48px; height:48px; border-radius:17px; transition:transform 300ms ease; }
.ac-app-catalog__icon > :is(svg,img) { display:block; width:30px; height:30px; object-fit:contain; }
.ac-app-catalog__item:hover .ac-app-catalog__icon { transform:translateY(-2px); }
.ac-app-catalog__copy { display:block; min-width:0; }
.ac-app-catalog__name { display:block; font-size:15px; line-height:1.5; font-weight:500; letter-spacing:-.01em; }
.ac-app-catalog__detail { display:block; margin-top:4px; color:var(--ac-app-muted,var(--ac-app-theme-muted)); font-size:13.5px; line-height:1.375; text-wrap:pretty; }
@container (max-width:979px) { .ac-app-catalog__layout { grid-template-columns:1fr; gap:40px; } .ac-app-catalog__intro h2 { max-width:20ch; font-size:56px; } }
@container (max-width:599px) { .ac-app-catalog__layout { padding-inline:20px; } .ac-app-catalog__intro h2 { font-size:44px; } .ac-app-catalog__grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .ac-app-catalog__grid > li:last-child:nth-child(odd) { grid-column:span 2; } .ac-app-catalog__item { padding:20px; } }
:where([data-theme='dark'],.dark) .ac-app-catalog { --ac-app-theme-surface:#1b1a22; --ac-app-theme-ink:#f4f2fb; --ac-app-theme-muted:#b6b1ca; --ac-app-theme-line:#383541; --ac-app-theme-hover:#25222f; color-scheme:dark; }
@media (prefers-reduced-motion:reduce) { .ac-app-catalog__item,.ac-app-catalog__icon { transition:none; } }
